package com.snoworca.naruserve.proxy;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import com.snoworca.naruserve.RestApp;
import com.snoworca.naruserve.testing.InMemoryHttpAdapter;
import com.snoworca.naruserve.testing.InMemoryHttpAdapter.ClientRequest;
import com.snoworca.naruserve.testing.InMemoryHttpAdapter.ClientResponse;
import com.snoworca.naruserve.testing.TestApp;
import java.io.Closeable;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.TimeUnit;
import org.junit.After;
import org.junit.Test;

public class ReviewProbe1Test {
    private final InMemoryHttpAdapter adapter = new InMemoryHttpAdapter();
    private final TestApp t = TestApp.create(adapter);
    private final RestApp app = t.app();
    private final List<Closeable> closeables = new ArrayList<>();
    private final List<Throwable> errors = Collections.synchronizedList(new ArrayList<Throwable>());

    @After
    public void tearDown() throws IOException {
        app.shutdown(2, TimeUnit.SECONDS);
        for (Closeable c : closeables) c.close();
    }

    private ClientResponse go(String method, String raw) throws IOException {
        RawBackend b = RawBackend.answering(raw);
        closeables.add(b);
        app.use("/api", Proxy.to(b.url()));
        app.onError((error, req, res) -> errors.add(error));
        t.start();
        return adapter.send(ClientRequest.of(method, "/api/x"));
    }

    @Test(timeout = 30000)
    public void http10InterimThenHttp11ChunkedIsDecoded() throws IOException {
        ClientResponse r = go("GET", "HTTP/1.0 100 Continue\r\n\r\nHTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n5\r\nhello\r\n0\r\n\r\n");
        assertEquals("errors " + errors, 200, r.status());
        assertEquals("hello", r.text());
        assertTrue(errors.toString(), errors.isEmpty());
    }

    @Test(timeout = 30000)
    public void http11InterimThenHttp10ChunkedIsInvalid() throws IOException {
        ClientResponse r = go("GET", "HTTP/1.1 100 Continue\r\n\r\nHTTP/1.0 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n5\r\nhello\r\n0\r\n\r\n");
        assertEquals(502, r.status());
        assertSame(ProxyException.Kind.INVALID_RESPONSE, ((ProxyException) errors.get(0)).kind());
    }

    @Test(timeout = 30000)
    public void http10BareLfChunkedIsInvalid() throws IOException {
        ClientResponse r = go("GET", "HTTP/1.0 200 OK\nTransfer-Encoding: chunked\n\n5\r\nhello\r\n0\r\n\r\n");
        assertEquals(502, r.status());
        assertSame(ProxyException.Kind.INVALID_RESPONSE, ((ProxyException) errors.get(0)).kind());
    }

    @Test(timeout = 30000)
    public void http10HeadWithTeAndClRelaysLength() throws IOException {
        ClientResponse r = go("HEAD", "HTTP/1.0 200 OK\r\nTransfer-Encoding: chunked\r\nContent-Length: 10\r\n\r\n");
        assertEquals(200, r.status());
        assertEquals("10", r.header("Content-Length"));
        assertEquals(0, r.body().length);
        assertTrue(errors.toString(), errors.isEmpty());
    }

    @Test(timeout = 30000)
    public void http10304WithTeAndClRelaysLength() throws IOException {
        ClientResponse r = go("GET", "HTTP/1.0 304 Not Modified\r\nTransfer-Encoding: chunked\r\nContent-Length: 10\r\n\r\n");
        assertEquals(304, r.status());
        assertEquals(0, r.body().length);
        assertTrue(errors.toString(), errors.isEmpty());
    }

    @Test(timeout = 30000)
    public void http10ContentLengthWorks() throws IOException {
        ClientResponse r = go("GET", "HTTP/1.0 200 OK\r\nContent-Length: 5\r\n\r\nhello");
        assertEquals(200, r.status());
        assertEquals("hello", r.text());
        assertEquals("5", r.header("Content-Length"));
        assertTrue(errors.toString(), errors.isEmpty());
    }

    @Test(timeout = 30000)
    public void http19ChunkedStillDecoded() throws IOException {
        ClientResponse r = go("GET", "HTTP/1.9 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n5\r\nhello\r\n0\r\n\r\n");
        assertEquals(200, r.status());
        assertEquals("hello", r.text());
    }

    @Test(timeout = 30000)
    public void http10GzipTeIsInvalid() throws IOException {
        ClientResponse r = go("GET", "HTTP/1.0 200 OK\r\nTransfer-Encoding: gzip\r\n\r\nxx");
        assertEquals(502, r.status());
    }
}
